    list = (p && p.props && p.props.pageProps && p.props.pageProps.list) || [];
  } catch (e) { continue; }
  for (let i = 0; i < list.length; i++) {
    if (out.length >= 10) { break; }
    const n = list[i] || {};
    const d = n.data || {};
    if (!d.title || !n.id) { continue; }
    const tg = Array.isArray(n.tags) ? n.tags : [];
    let blocked = false;
