const tz = 'Asia/Makassar';
const nowTz = $now.setZone(tz);
const runDate = nowTz.toFormat('yyyy-MM-dd');
const runLabel = nowTz.setLocale('id').toFormat('cccc, d LLLL yyyy');
const APOS = String.fromCharCode(39);
const MO = String.fromCharCode(226) + String.fromCharCode(128);

const ent = function (s) {
  let v = String(s == null ? '' : s);
  v = v.split(MO + String.fromCharCode(153)).join(String.fromCharCode(8217));
  v = v.split(MO + String.fromCharCode(156)).join('"');
  v = v.split(MO + String.fromCharCode(157)).join('"');
  v = v.split(MO + String.fromCharCode(147)).join('-');
  v = v.split(MO + String.fromCharCode(148)).join('-');
  v = v.split(MO + String.fromCharCode(166)).join('...');
  v = v.replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); });
  v = v.replace(/&#x([0-9a-fA-F]+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 16)); });
  v = v.replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  return v.replace(/\s+/g, ' ').trim();
};

const today = $('Gabung Semua Sumber').all()
  .map(function (i) { return i.json; })
  .filter(function (j) { return j && j.key && j.title; });
const history = $input.all()
  .map(function (i) { return i.json; })
  .filter(function (j) { return j && j.run_date && j.key; });

const otherDates = {};
history.forEach(function (r) {
  const d = String(r.run_date);
  if (d && d !== runDate) { otherDates[d] = 1; }
});
const dateList = Object.keys(otherDates).sort();
const prevDate = dateList.length ? dateList[dateList.length - 1] : null;
const prevRank = {};
if (prevDate) {
  history.forEach(function (r) {
    if (String(r.run_date) === prevDate) { prevRank[r.key] = Number(r.rank) || 0; }
  });
}
const seenDates = {};
history.forEach(function (r) {
  if (!seenDates[r.key]) { seenDates[r.key] = {}; }
  seenDates[r.key][String(r.run_date)] = 1;
});

const esc = function (s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};
const fmt = function (v) {
  const n = Number(v) || 0;
  if (n <= 0) { return null; }
  if (n >= 1000000) { return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'jt'; }
  if (n >= 1000) { return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'rb'; }
  return String(n);
};

const rows = today.map(function (j) {
  const hist = seenDates[j.key] || {};
  const daysSeen = Object.keys(hist).length;
  const pr = prevRank[j.key] || 0;
  const rk = Number(j.rank) || 0;
  return {
    source: j.source, rank: rk, key: j.key,
    title: ent(j.title), url: j.url,
    rating: Number(j.rating) || 0,
    votes: Number(j.votes) || 0,
    votesLabel: j.votesLabel || 'suara',
    views: Number(j.views) || 0,
    chapters: Number(j.chapters) || 0,
    genres: Array.isArray(j.genres) ? j.genres.map(ent).filter(Boolean) : [],
    blurb: ent(j.blurbId || j.blurbEn || ''),
    isNew: daysSeen === 0, streak: daysSeen + 1,
    prevRank: pr, delta: pr ? pr - rk : 0
  };
});

const ALL_SOURCES = ['WTR Lab', 'Royal Road', 'NovelUpdates', 'MeioNovel'];
const order = {};
ALL_SOURCES.forEach(function (s, i) { order[s] = i; });
const groups = {};
rows.forEach(function (r) {
  if (!groups[r.source]) { groups[r.source] = []; }
  groups[r.source].push(r);
});
const sourceNames = Object.keys(groups).sort(function (a, b) {
  return (order[a] == null ? 99 : order[a]) - (order[b] == null ? 99 : order[b]);
});
sourceNames.forEach(function (s) { groups[s].sort(function (a, b) { return a.rank - b.rank; }); });

const newOnes = rows.filter(function (r) { return r.isNew; });
let pool = newOnes.filter(function (r) { return r.rating > 0; });
if (!pool.length) { pool = rows.filter(function (r) { return r.rating > 0; }); }
pool = pool.slice().sort(function (a, b) { return b.rating - a.rating; });
const pick = pool.length ? pool[0] : (rows.length ? rows[0] : null);
const missing = ALL_SOURCES.filter(function (s) { return !groups[s]; });

const chip = function (g) {
  return '<span style="display:inline-block;background:#eef2ff;color:#4338ca;font-size:11px;padding:2px 8px;border-radius:11px;margin:0 4px 4px 0;">' + esc(g) + '</span>';
};

