    if (r.rating > 0) { bits.push('&#9733; ' + r.rating.toFixed(2)); }
    if (fmt(r.chapters)) { bits.push(fmt(r.chapters) + ' bab'); }
    if (fmt(r.views)) { bits.push(fmt(r.views) + ' baca'); }
    if (fmt(r.votes)) { bits.push(fmt(r.votes) + ' ' + r.votesLabel); }
    if (bits.length) { h.push('<div style="font-size:12px;color:#9ca3af;margin-top:6px;">' + bits.join(' &middot; ') + '</div>'); }
    if (r.blurb) { h.push('<div style="font-size:13px;color:#4b5563;margin-top:8px;line-height:1.6;">' + esc(r.blurb) + '</div>'); }
    h.push('</td></tr></table>');
    h.push('</div>');
  });
  h.push('</div>');
