if (missing.length) {
  h.push('<div style="margin-top:18px;background:#fff7ed;border-radius:12px;padding:14px 18px;font-size:13px;color:#9a3412;">');
  h.push('Sumber tidak terbaca hari ini: ' + esc(missing.join(', ')) + '.');
  h.push('</div>');
}
h.push('<div style="margin-top:20px;text-align:center;font-size:11px;color:#9ca3af;line-height:1.6;">');
h.push('Dikirim otomatis oleh n8n &middot; ' + nowTz.toFormat('HH:mm') + ' WITA');
h.push('</div></div></div>');

const subject = 'Novel Harian ' + nowTz.toFormat('dd LLL') + ' - ' + rows.length + ' judul, ' + newOnes.length + ' baru';
